using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using SkyLab.Web.Models;using SkyLab.Web.Services;
namespace SkyLab.Web.Pages.Clienti.Sedi;
public sealed class EditModel(CustomerService service):PageModel{[BindProperty]public SiteEditModel Sede{get;set;}=new();public string Cliente{get;private set;}="";public async Task<IActionResult> OnGetAsync(int? id,int? clienteId,CancellationToken ct){if(id.HasValue){var x=await service.SiteAsync(id.Value,ct);if(x is null)return NotFound();Sede=x;}else if(clienteId.HasValue)Sede.CustomerId=clienteId.Value;else return BadRequest();Cliente=await service.CustomerNameAsync(Sede.CustomerId,ct);return Page();}public async Task<IActionResult> OnPostAsync(CancellationToken ct){Cliente=await service.CustomerNameAsync(Sede.CustomerId,ct);if(!ModelState.IsValid)return Page();await service.SaveSiteAsync(Sede,ct);return RedirectToPage("Index",new{clienteId=Sede.CustomerId});}}
